class Solution {
public:
    int beautifulSplits(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> lcp(n + 1, vector<int>(n + 1, 0));
        for (int i = n - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                if (nums[i] == nums[j]) lcp[i][j] = 1 + lcp[i + 1][j + 1];
            }
        }
        int ans = 0;
        for (int i = 0; i < n - 2; ++i) {
            int len1 = i + 1;
            for (int j = i + 1; j < n - 1; ++j) {
                int len2 = j - i, len3 = n - 1 - j;
                bool cond1 = (len2 >= len1) && (lcp[0][i + 1] >= len1);
                bool cond2 = (len3 >= len2) && (lcp[i + 1][j + 1] >= len2);
                if (cond1 || cond2) ans++;
            }
        }
        return ans;
    }
};

